"""
GitHub client module for interacting with GitHub API.
"""
from github3 import GitHub


class GitHubClient:
    def __init__(self, token):
        """Initialize GitHub client with authentication token."""
        self.client = GitHub(token=token)

    def search_code(self, query, sort='indexed', order='desc'):
        """Search for code matching the given query."""
        return self.client.search_code(query, sort=sort, order=order)

    def repository(self, owner, name):
        """Get a repository by owner and name."""
        return self.client.repository(owner, name)
